import{_ as t,o,c as a,f as n}from"./chunks/framework.o8v22TzC.js";const r="/images/heroes-olden-era/03.jpg",i="/images/heroes-olden-era/07.jpg",m=JSON.parse(`{"title":"Heroes of Might and Magic: Olden Era | Haven Faction — A Beginner's Starting Guide","description":"Haven is the most forgiving faction in the game for new players. Here's how to open strong, build in the right order, and not throw your early game away.","frontmatter":{"title":"Heroes of Might and Magic: Olden Era | Haven Faction — A Beginner's Starting Guide","description":"Haven is the most forgiving faction in the game for new players. Here's how to open strong, build in the right order, and not throw your early game away.","date":"2026-05-04","category":"Player Insights","tags":["haven","beginner","faction-guide","early-game","combat","build-order"],"featured":false,"order":8,"cover":"/images/heroes-olden-era/03.jpg","gameHeader":"/images/heroes-olden-era/header.jpg","head":[["meta",{"property":"og:title","content":"Haven Faction — A Beginner's Starting Guide | Scroll Tome"}],["meta",{"property":"og:description","content":"Haven is the most forgiving faction in the game for new players. Here's how to open strong, build in the right order, and not throw your early game away."}],["link",{"rel":"canonical","href":"https://scrolltome.com/guide/08-haven-faction-starter-guide"}],["link",{"rel":"canonical","href":"https://scrolltome.com/guide/08-haven-faction-starter-guide"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Heroes of Might and Magic: Olden Era | Haven Faction — A Beginner's Starting Guide\\",\\"description\\":\\"Haven is the most forgiving faction in the game for new players. Here's how to open strong, build in the right order, and not throw your early game away.\\",\\"datePublished\\":\\"2026-05-04\\",\\"dateModified\\":\\"2026-05-04\\",\\"url\\":\\"https://scrolltome.com/guide/08-haven-faction-starter-guide\\",\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Scroll Tome\\",\\"url\\":\\"https://scrolltome.com\\"},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://scrolltome.com/guide/08-haven-faction-starter-guide\\"}}"]]},"headers":[],"relativePath":"guide/08-haven-faction-starter-guide.md","filePath":"guide/08-haven-faction-starter-guide.md"}`),s={name:"guide/08-haven-faction-starter-guide.md"};function h(l,e,g,d,u,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>Quick note before we start: this is a buy-once game. No battle pass, no premium currency, no locked factions. Whatever faction you pick, you&#39;re getting the full thing.</p><p>If you&#39;re new and not sure where to start — pick Haven. It&#39;s not flashy, but it&#39;s the most forgiving faction in the game. The units do what you expect them to do, the build order makes intuitive sense, and the early game doesn&#39;t punish you as hard for small mistakes.</p><p>Here&#39;s what I&#39;d tell someone sitting down with Haven for the first time.</p><p><img src="'+r+'" alt="Haven — the human faction town, built around order and steady growth"></p><hr><h2 id="the-three-units-you-ll-rely-on" tabindex="-1">The three units you&#39;ll rely on <a class="header-anchor" href="#the-three-units-you-ll-rely-on" aria-label="Permalink to &quot;The three units you&#39;ll rely on&quot;">​</a></h2><p><strong>Crossbowmen</strong> are your main damage source early on. They&#39;re ranged, they hit consistently, and when positioned well they can clear neutral camps without taking a scratch. Most of your early fights revolve around keeping them safe and letting them work.</p><p><strong>Paladins</strong> go in front. They&#39;re there to absorb hits, not deal damage. Their job is to stand between your Crossbowmen and anything that wants to kill them. They&#39;re tough enough to do it, and tough enough that most neutral stacks will waste attacks on them while your backline fires freely.</p><p><strong>Cavalry</strong> is the flexible piece. High movement speed means they can reposition mid-fight — use them to bait retaliation swings from slow enemies, or to reach the enemy&#39;s backline when they&#39;ve left their own ranged units exposed. They&#39;re not your primary damage, but they control how the fight plays out.</p><hr><h2 id="building-order" tabindex="-1">Building order <a class="header-anchor" href="#building-order" aria-label="Permalink to &quot;Building order&quot;">​</a></h2><p>There&#39;s no need to overthink this. The goal in the first few days is stable income, then troops, then upgrades — in that order.</p><p><strong>Economy first:</strong> Start with the Town Hall, then get a Sawmill and a Mine running. Gold and wood are the two resources that bottleneck almost everything else early, and the sooner those buildings are producing, the smoother the rest of the week goes.</p><p><strong>Then troops and magic:</strong> Once income is stable, build the Barracks and a Mage Guild. The Barracks lets you recruit in volume. The Mage Guild at even Level 1 unlocks spells that can swing fights — don&#39;t skip it.</p><p><strong>Then upgrades:</strong> Castle and Training Grounds come after. They raise your unit tier cap and strengthen your town defenses, which matters more in Week 2 and beyond than in the opening days.</p><hr><h2 id="how-to-fight-early-neutrals" tabindex="-1">How to fight early neutrals <a class="header-anchor" href="#how-to-fight-early-neutrals" aria-label="Permalink to &quot;How to fight early neutrals&quot;">​</a></h2><p>Scale up gradually. Start with the camps right outside your town — the ones guarded by basic units like Crossbowmen-equivalent neutrals or wolves. Work up to goblin camps after that. Don&#39;t jump straight into anything that makes you uncertain.</p><p><strong>Formation every fight:</strong> Paladins up front in a line, Crossbowmen placed behind them. Cavalry on the sides or held back until you see an opening.</p><p><strong>Priority target:</strong> whoever on the enemy side is doing ranged damage. Kill them first. Enemy ranged units will chew through your Crossbowmen if left alone, and your Paladins can&#39;t protect against something shooting over them.</p><p><strong>Use your Cavalry to bait.</strong> Slow enemies — anything with low initiative — will waste their retaliation swing on a Cavalry unit you deliberately moved into range. That means your Crossbowmen get another turn of free shots before anything attacks them.</p><p>One last thing: turn off auto-battle. The AI makes bad decisions with Haven&#39;s toolkit specifically. Manual control isn&#39;t hard once you know the three units, and you&#39;ll lose far fewer troops.</p><p><img src="'+i+'" alt="Haven units in a field engagement — Paladins forward, ranged units working behind"></p><hr><p>Get the economy going in the first two or three days, keep your Crossbowmen alive, and don&#39;t pick fights you&#39;re not ready for. Haven rewards patience more than aggression in the early game — once you&#39;ve got a full stack of each unit type and a couple of Mage Guild spells, that&#39;s when you start pushing out.</p>',25)])])}const y=t(s,[["render",h]]);export{m as __pageData,y as default};
